pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1 ether);

        // Adversarial logger: its AddMessage always reverts. In P, SetLogFile stores it,
        // so Deposit's Log.AddMessage reverts; in M, Log stays address(0) and Deposit succeeds.
        RevertingLog log = new RevertingLog();
        c.SetLogFile(address(log));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: with a rejecting logger configured via SetLogFile, every Deposit must revert.
        assertTrue(!ok);
    }
}

contract RevertingLog {
    function AddMessage(address, uint256, string calldata) external pure {
        revert();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newLog) public {
        vm.assume(actor != address(0));
        vm.assume(newLog != address(0));

        vm.prank(actor);
        c.SetLogFile(newLog);
        address before = c.Log();

        vm.prank(actor);
        c.Initialized();

        vm.prank(actor);
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }

        // Rule: after initialization, SetLogFile always reverts and the Log
        // address is locked. The mutant allows it to succeed and change.
        assertTrue(!ok && c.Log() == before);
    }
}

