contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint _val, uint _am) public {
        require(_am < _val);
        require(address(this).balance >= _am);
        c.SetMinSum(_val);
        c.Deposit{value: _am}();
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

